# owner: platform
"""Weekly timesheet rows built from a list of shifts."""

from hourglass.models import Shift


def _add(totals: dict, shift: Shift) -> None:
    count, mins = totals.get(shift.worker, (0, 0))
    mins += shift.span.minutes
    totals[shift.worker] = (count + 1, mins)


def _totals(shifts: list[Shift]) -> dict:
    totals = {}
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("blank worker name")
        _add(totals, shift)
    return totals


def _busy(item) -> tuple:
    return (-item[1][1], item[0])


def _line(name: str, count: int, mins: int) -> str:
    return f"{name}: {count} shifts, {mins / 60:.1f} hours"


# ---
def timesheet_lines(shifts: list[Shift]) -> list[str]:
    """One line per worker, most total hours first."""
    if not shifts:
        raise ValueError("no shifts given")
    ranked = sorted(_totals(shifts).items(), key=_busy)
    return [_line(name, *data) for name, data in ranked]

