# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Span, Shift


def make_shift(worker, begin, stop, when="mon"):
    return Shift(worker, when, Span(begin, stop))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        lines = timesheet_lines([
            make_shift("Ana", 540, 600),
            make_shift("Brisa", 540, 780),
            make_shift("Ana", 540, 630, "tue")
        ])
        self.assertEqual(lines, [
            "Brisa: 1 shifts, 4.0 hours",
            "Ana: 2 shifts, 2.5 hours"
        ])

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_lines([make_shift("  ", 540, 600)])
